const txnTemplateSpark = `-- name: TxnTemplateSpark :many
SELECT t.template_id::uuid AS template_id,
       floor(extract(epoch FROM t.accepted_at - $1::timestamptz) / $2::float8)::int AS bucket,
       count(*)::bigint AS n
FROM transactional_messages t
JOIN messages m ON m.id = t.message_id
WHERE t.workspace_id = $3 AND t.accepted_at >= $1::timestamptz AND t.template_id IS NOT NULL
  AND m.status IN ('sent','delivered','deferred','bounced','complained')
  AND ($4::boolean OR NOT t.test)
GROUP BY 1, 2
`

type TxnTemplateSparkParams struct {
	Since         time.Time `json:"since"`
	BucketSeconds float64   `json:"bucketSeconds"`
	WorkspaceID   uuid.UUID `json:"workspaceId"`
	IncludeTest   bool      `json:"includeTest"`
}

type TxnTemplateSparkRow struct {
	TemplateID uuid.UUID `json:"templateId"`
	Bucket     int32     `json:"bucket"`
	N          int64     `json:"n"`
}

// Messages a provider accepted per template and bucket of a period.
func (q *Queries) TxnTemplateSpark(ctx context.Context, arg TxnTemplateSparkParams) ([]TxnTemplateSparkRow, error) {
	rows, err := q.db.Query(ctx, txnTemplateSpark,
		arg.Since,
		arg.BucketSeconds,
		arg.WorkspaceID,
		arg.IncludeTest,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TxnTemplateSparkRow{}
	for rows.Next() {
		var i TxnTemplateSparkRow
		if err := rows.Scan(&i.TemplateID, &i.Bucket, &i.N); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const txnTemplateStats = `-- name: TxnTemplateStats :many
SELECT t.template_id::uuid AS template_id,
       count(*) FILTER (WHERE m.status IN ('sent','delivered','deferred','bounced','complained'))::bigint AS sent,
       count(*) FILTER (WHERE m.status IN ('delivered','complained'))::bigint AS delivered,
       count(*) FILTER (WHERE m.status = 'bounced')::bigint AS bounced,
       count(*) FILTER (WHERE m.status = 'complained')::bigint AS complained,
       count(*) FILTER (WHERE m.status = 'deferred')::bigint AS deferred,
       count(*) FILTER (WHERE t.reject_reason <> '' AND NOT t.test)::bigint AS rejected,
       count(*) FILTER (WHERE m.status = 'failed')::bigint AS failed,
       count(*) FILTER (WHERE m.opened_at IS NOT NULL)::bigint AS opened,
       count(*) FILTER (WHERE m.clicked_at IS NOT NULL)::bigint AS clicked,
       coalesce((percentile_cont(0.5) WITHIN GROUP (ORDER BY extract(epoch FROM m.delivered_at - t.accepted_at) * 1000)
                 FILTER (WHERE m.delivered_at IS NOT NULL AND m.delivered_at >= t.accepted_at)), -1)::bigint AS median_ms,
       coalesce(max(t.accepted_at) FILTER (WHERE m.status IN ('sent','delivered','deferred','bounced','complained')), 'epoch'::timestamptz)::timestamptz AS last_sent_at,
       coalesce(bool_or(jsonb_array_length(t.attachments) > 0), false)::boolean AS attachments
FROM transactional_messages t
JOIN messages m ON m.id = t.message_id
WHERE t.workspace_id = $1 AND t.accepted_at >= $2 AND t.template_id IS NOT NULL
  AND ($3::boolean OR NOT t.test)
GROUP BY t.template_id
`

type TxnTemplateStatsParams struct {
	WorkspaceID uuid.UUID `json:"workspaceId"`
	Since       time.Time `json:"since"`
	IncludeTest bool      `json:"includeTest"`
}

type TxnTemplateStatsRow struct {
	TemplateID  uuid.UUID `json:"templateId"`
	Sent        int64     `json:"sent"`
	Delivered   int64     `json:"delivered"`
	Bounced     int64     `json:"bounced"`
	Complained  int64     `json:"complained"`
	Deferred    int64     `json:"deferred"`
	Rejected    int64     `json:"rejected"`
	Failed      int64     `json:"failed"`
	Opened      int64     `json:"opened"`
	Clicked     int64     `json:"clicked"`
	MedianMs    int64     `json:"medianMs"`
	LastSentAt  time.Time `json:"lastSentAt"`
	Attachments bool      `json:"attachments"`
}

// Each template's numbers over a period. Test messages are left out unless
// include_test; sent counts what a provider accepted; delivered includes
// messages complained about later; a soft bounce counts as a bounce.
func (q *Queries) TxnTemplateStats(ctx context.Context, arg TxnTemplateStatsParams) ([]TxnTemplateStatsRow, error) {
	rows, err := q.db.Query(ctx, txnTemplateStats, arg.WorkspaceID, arg.Since, arg.IncludeTest)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TxnTemplateStatsRow{}
	for rows.Next() {
		var i TxnTemplateStatsRow
		if err := rows.Scan(
			&i.TemplateID,
			&i.Sent,
			&i.Delivered,
			&i.Bounced,
			&i.Complained,
			&i.Deferred,
			&i.Rejected,
			&i.Failed,
			&i.Opened,
			&i.Clicked,
			&i.MedianMs,
			&i.LastSentAt,
			&i.Attachments,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

